<?php

declare(strict_types=1);

namespace Ethernize\Shield\Password;

/**
 * The native password_hash() family. The algorithm is the platform default unless one is given
 * (PASSWORD_ARGON2ID where the build has it). Salts are generated by PHP.
 */
final class NativeHasher implements Hasher
{
    /** Longer passwords are rejected instead of hashed, so a request cannot make the server burn CPU on megabytes. */
    public const MAX_LENGTH = 1024;

    private ?string $dummy = null;

    /**
     * @param array<string, int> $options
     */
    public function __construct(private readonly string|int|null $algorithm = PASSWORD_DEFAULT, private readonly array $options = [])
    {
    }

    public function hash(#[\SensitiveParameter] string $password): string
    {
        if (strlen($password) > self::MAX_LENGTH) {
            throw new \InvalidArgumentException('The password is too long.');
        }

        return password_hash($password, $this->algorithm, $this->options);
    }

    public function verify(#[\SensitiveParameter] string $password, string $hash): bool
    {
        return strlen($password) <= self::MAX_LENGTH && password_verify($password, $hash);
    }

    public function needsRehash(string $hash): bool
    {
        return password_needs_rehash($hash, $this->algorithm, $this->options);
    }

    public function dummyHash(): string
    {
        return $this->dummy ??= $this->hash(bin2hex(random_bytes(16)));
    }
}
